{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Estazolam, a chlorophenyl-containing heteroaromatic benzodiazepine, showed 87% oral bioavailability in healthy volunteers after a 4 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alprazolam, a structurally related triazolobenzodiazepine, had an absolute oral bioavailability of 0.84 in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Clobazam oral solution bioavailability was 87-100% and food did not affect its absorption, directly relevant to the fed-state condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Tenidap, a chlorophenyl heteroaromatic drug, had an absolute bioavailability of 85% in healthy male volunteers after oral versus IV dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Vorozole, a chiral heteroaryl with a p-chlorophenyl group, had excellent oral bioavailability in postmenopausal women.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Adinazolam, a triazolobenzodiazepine, had an absolute oral bioavailability of approximately 40% in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental oral bioavailability values for structurally related chlorophenyl/heteroaromatic drugs are at or above 20% (mostly 40-100%), and absolute measurements for alprazolam, adinazolam, tenidap, and vorozole support high F. Low Morgan similarities and lack of query-specific data temper confidence, but no affirmative threshold-relevant evidence supports low F.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule.",
    "All retrieved analogues have low Morgan similarity (0.20-0.27), limiting structural transferability.",
    "Fed-state effect on the query is not directly measured; only clobazam explicitly reports food-independent absorption.",
    "Conflicting bupropion bioavailability records exist, but bupropion is structurally distant and not used as a primary anchor."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

